#include <iostream>
#include <cstring>
#include <vector>
#include <queue>
#include <algorithm>
using namespace std;

#define SIZE 202
#define INF_VAL 0x3f3f3f3f

int flow_flow[SIZE][SIZE], capacity_flow[SIZE][SIZE], prev_node[SIZE], queue_arr[SIZE], dist_arr[SIZE];

int max_flow(int total_nodes, int src, int dst) {
    while (true) {
        memset(prev_node, -1, sizeof(prev_node));
        dist_arr[src] = INF_VAL;
        int f = 0, r = 0;
        queue_arr[r++] = src;
        while (f < r && prev_node[dst] < 0) {
            int cur = queue_arr[f++];
            for (int node = 0; node < total_nodes; ++node) {
                if (prev_node[node] < 0) {
                    int res_cap = capacity_flow[cur][node] - flow_flow[cur][node];
                    if (res_cap > 0) {
                        prev_node[queue_arr[r++] = node] = cur;
                        dist_arr[node] = min(dist_arr[cur], res_cap);
                    }
                }
            }
        }
        if (prev_node[dst] < 0) break;
        int aug = dist_arr[dst];
        for (int nd = dst; nd != src; nd = prev_node[nd]) {
            flow_flow[prev_node[nd]][nd] += aug;
            flow_flow[nd][prev_node[nd]] -= aug;
        }
    }
    int total = 0;
    for (int nd = 0; nd < total_nodes; ++nd)
        total += flow_flow[src][nd];
    return total;
}

char board_in[11][11], board_out[11][11];
int zombie_i, zombie_j, move_dx[4] = {0,0,1,-1}, move_dy[4] = {1,-1,0,0};
int dist_table[101][101];
int grid_size, time_limit;
vector<int> lst_row, lst_col;

void bfs_compute(int si, int sj, int* result_dist, bool check_flag) {
    queue<pair<int,int>> q;
    result_dist[si*grid_size + sj] = 0;
    q.emplace(si, sj);
    while (!q.empty()) {
        auto [i,j] = q.front(); q.pop();
        int idx = i*grid_size + j;
        int d_val = result_dist[idx];
        if (check_flag) {
            if (dist_table[zombie_i*grid_size + zombie_j][idx] <= d_val || time_limit <= d_val) {
                if (dist_table[zombie_i*grid_size + zombie_j][idx] < d_val || time_limit < d_val)
                    result_dist[idx] = INF_VAL + 1;
                continue;
            }
        }
        for (int k = 0; k < 4; ++k) {
            int ni = i + move_dx[k], nj = j + move_dy[k];
            if (ni < 0 || nj < 0 || ni == grid_size || nj == grid_size) continue;
            char ch = board_out[ni][nj];
            if (ch < '0' || ch > '9') continue;
            int nidx = ni*grid_size + nj;
            if (result_dist[nidx] != INF_VAL) continue;
            result_dist[nidx] = d_val + 1;
            q.emplace(ni, nj);
        }
    }
}

void prepare_graph() {
    for (int i = 0; i < grid_size; ++i) {
        for (int j = 0; j < grid_size; ++j) {
            char c = board_out[i][j];
            if (c >= '1' && c <= '9') {
                lst_row.push_back(i);
                lst_col.push_back(j);
                int idx = i*grid_size + j;
                capacity_flow[idx + 2 + grid_size*grid_size][1] = c - '0';
            }
        }
    }
    int z_idx = zombie_i*grid_size + zombie_j;
    for (int i = 0; i < grid_size; ++i) {
        for (int j = 0; j < grid_size; ++j) {
            char c = board_in[i][j];
            if (c >= '1' && c <= '9') {
                int idx = i*grid_size + j;
                capacity_flow[0][idx + 2] = c - '0';
                for (int k = 0; k < lst_row.size(); ++k) {
                    int ri = lst_row[k], ci = lst_col[k];
                    int q_idx = ri*grid_size + ci;
                    if (dist_table[idx][q_idx] < INF_VAL)
                        capacity_flow[idx + 2][q_idx + 2 + grid_size*grid_size] = INF_VAL;
                }
            }
        }
    }
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    cin >> grid_size >> time_limit;
    memset(dist_table, 0x3f, sizeof(dist_table));
    for (int i = 0; i < grid_size; ++i) cin >> board_in[i];
    for (int i = 0; i < grid_size; ++i) cin >> board_out[i];
    for (int i = 0; i < grid_size; ++i) {
        for (int j = 0; j < grid_size; ++j) {
            if (board_in[i][j] == 'Z') {
                zombie_i = i;
                zombie_j = j;
            }
        }
    }
    bfs_compute(zombie_i, zombie_j, dist_table[zombie_i*grid_size + zombie_j], false);
    for (int i = 0; i < grid_size; ++i) {
        for (int j = 0; j < grid_size; ++j) {
            if (board_in[i][j] >= '1' && board_in[i][j] <= '9')
                bfs_compute(i, j, dist_table[i*grid_size + j], true);
        }
    }
    prepare_graph();
    cout << max_flow(2 + grid_size*grid_size + grid_size*grid_size, 0, 1) << '\n';
    return 0;
}
